#!/usr/bin/env python3
"""Generate customer-owned bilingual Builder/Form seed data; no database writes."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]/'web/seed-data/eduhope'
SERIAL=0

def identity(prefix):
    global SERIAL
    SERIAL+=1
    return f'eduhope-{prefix}-{SERIAL}'


def text(kind,en,ar='',**extra):
    element={'id':identity('element'),'type':kind,'name':kind,'content':en,
             'styles':{'color':'#002A60','width':'100%','textAlign':'start','lineHeight':'1.7'},'action':{'type':'none'},**extra}
    if kind=='list':element['styles'].update(height='320px',minHeight='280px')
    if ar:element['localized']={'content':{'en':en,'ar':ar}}
    if kind=='list':
        element['listItems']=en.split('\n')
        if ar:element['localized']['listItems']={'en':en.split('\n'),'ar':ar.split('\n')}
    return element


def section(name,elements,background='#FFFFFF',columns=1):
    return {'id':identity('section'),'name':name,'layout':{'width':'full','paddingY':'large','background':background},
            'rows':[{'id':identity('row'),'layout':{'columns':columns,'align':'start','gap':'large'},
                     'columns':[{'id':identity('column'),'elements':items} for items in (elements if columns>1 else [elements])]}]}


def heading(en,ar,tag='h2'):
    return text('heading',en,ar,headingTag=tag,styles={'width':'100%','color':'#002A60','fontWeight':'750','fontSize':'36px' if tag=='h2' else '52px','textAlign':'start','lineHeight':'1.25'})


def button(en,ar,destination):
    action={'type':'goToPage','pageId':'eduhope-page-'+destination} if not destination.startswith('ref:') else {'type':'openUrl','url':destination}
    return text('button',en,ar,action=action,backgroundColor='#088848',textColor='#FFFFFF',hoverBackgroundColor='#006C39',hoverTextColor='#FFFFFF',styles={'borderRadius':'999px','fontWeight':'700'})


def form_block(key):
    return {'id':identity('form-placement'),'type':'academyForm','name':'Learning form placement','content':'','styles':{'width':'100%'},'academy':{'formId':'ref:forms.'+key},'action':{'type':'none'}}


def field(key,en,ar,kind='shortText',required=True,maximum=120):
    value={'id':key,'type':kind,'label':en,'localized':{'label':{'en':en,'ar':ar}},'required':required,'placeholder':('Write your response' if kind=='paragraph' else 'Enter '+en.lower()),'helpText':('PDF, PNG or JPEG; up to 5 MB' if kind=='file' else ''),'validation':{'maxLength':maximum} if kind in {'shortText','paragraph'} else {}}
    if kind=='checkboxes':value.update(options=['I accept'],localized={'label':{'en':en,'ar':ar},'options':{'en':['I accept'],'ar':['أوافق']}})
    if kind=='file':value['maxFileSizeMb']=5
    value['localized']['placeholder']={'en':value['placeholder'],'ar':'اكتب إجابتك' if kind=='paragraph' else 'أدخل '+ar}
    if kind=='file':value['localized']['helpText']={'en':value['helpText'],'ar':'PDF أو PNG أو JPEG؛ بحد أقصى 5 ميغابايت'}
    return value


def definition(key,en,ar,items,kind='none'):
    schema={'title':en,'description':'Your information is private and reviewed by authorized academy staff. This is a local demonstration.','languageMode':'bilingual','defaultLanguage':'ar','localized':{'title':{'en':en,'ar':ar},'description':{'ar':'معلوماتك خاصة ويراجعها موظّفو الأكاديمية المخوّلون. هذه معاينة محلية تجريبية.'},'submitLabel':{'en':'Submit','ar':'إرسال'},'successMessage':{'en':'Thank you. Your response was received.','ar':'شكراً لك. تم استلام ردّك.'}},'submitLabel':'Submit','successMessage':'Thank you. Your response was received.','pageMode':'single','access':'public' if kind=='none' else 'authenticated','notifyOwner':True,'confirmSubmitter':kind!='none','sections':[{'id':key+'-page','title':'','fields':items}],'logicRules':[]}
    if kind!='none':schema['workflow']={'kind':kind,'termsFieldId':'terms'}
    return {'key':'forms.'+key,'name':en,'status':'active','schema':schema,'demo_only':True}


def main():
    ROOT.mkdir(parents=True,exist_ok=True)
