    (ROOT/'manifest.json').write_text(json.dumps({'package':'eduhope','version':1,'languages':['en','ar'],'website':'website.json','settings':'settings.json','teaching':'teaching.json','assessments':'assessments.json','illustrations':'illustrations/','forms':'forms.json','course':'course.json','media':'media.json','provisional':True,'production_writes_authorized':False,'required_schema':{'website_forms':141,'advanced_learning':143,'general_decisions':144},'exclude_from_import':['auth_users','sessions','private_responses','application_history','payments','wallet_records','demo_enrolments']},indent=2)+'\n')
